-- mergeAsts must keep every node when spans overlap without one containing
-- the other (which LINE pragmas and code generated by Template Haskell can
-- produce). It used to drop one of the nodes and emit the other one twice.
module Main where

import GHC.Iface.Ext.Types
import GHC.Iface.Ext.Utils
import GHC.Types.SrcLoc
import GHC.Data.FastString
import qualified Data.Map as M
import qualified Data.Set as S
import Data.List (sort)

node :: String -> (Int, Int) -> (Int, Int) -> [HieAST a] -> HieAST a
node name (l1, c1) (l2, c2) kids =
  Node (mkSourcedNodeInfo SourceInfo (simpleNodeInfo (fsLit name) (fsLit "Test"))) sp kids
  where
    f = fsLit "T.hs"
    sp = mkRealSrcSpan (mkRealSrcLoc f l1 c1) (mkRealSrcLoc f l2 c2)

labels :: HieAST a -> [String]
labels (Node (SourcedNodeInfo m) _ kids) =
  [ unpackFS (nodeAnnotConstr a) | ni <- M.elems m, a <- S.toList (nodeAnnotations ni) ]
  ++ concatMap labels kids

check :: String -> [HieAST a] -> [HieAST a] -> IO ()
check name input output = do
  let want = sort (concatMap labels input)
      got  = sort (concatMap labels output)
  putStrLn $ name ++ ": " ++ unwords got
    ++ (if got == want then "" else "  (expected " ++ unwords want ++ ")")

main :: IO ()
main = do
  -- A starts inside B and ends after it.
  let a = node "A" (1, 3) (1, 8) []
      b = node "B" (1, 1) (1, 5) []
  check "overlap a b" [a, b] (mergeAsts [a] [b])
  check "overlap b a" [a, b] (mergeAsts [b] [a])

  -- A chain of overlapping spans, in different orders.
  let x = node "X" (1, 1) (1, 6) []
      y = node "Y" (1, 4) (1, 9) []
      z = node "Z" (1, 7) (1, 12) []
  check "chain xyz" [x, y, z] (mergeSortAsts [x, y, z])
  check "chain zyx" [x, y, z] (mergeSortAsts [z, y, x])
  check "chain yxz" [x, y, z] (mergeSortAsts [y, x, z])

  -- An overlapping node merged into the children of an enclosing node.
  let p = node "P" (1, 1) (3, 1) [node "C1" (1, 2) (1, 10) [], node "C2" (2, 1) (2, 5) []]
      q = node "Q" (1, 5) (2, 3) []
  check "nested" [p, q] (mergeAsts [p] [q])
